label("$y=-50$",(6,-50));
label("$x$",(4.5,0),E);
label("$f(x)=x^3$",(0,4.5^3),N);

int n;
for(n=-3;n<=3;++n)

{

dot((n,n^3));

}
dot((-4,-64),NoFill);
dot((4,64),NoFill);
label("$(3,27)$",(3,27),W);
label("$(4,64)$",(4,64),W);[/asy]

